import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as n,a as r}from"./chunks/M-S-LCS-AC5a.MFTz2ahv.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as o}from"./chunks/M-S-DS2l2.BdmWUi3X.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as l,o as p,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const D=JSON.parse('{"title":"Calibration avancée","description":"","frontmatter":{"source_hash":"d8b53e5b65","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/calibrate/advancedcal.md","filePath":"fr/calibrate/advancedcal.md"}'),u={name:"fr/calibrate/advancedcal.md"};function m(b,a,g,v,h,f){return p(),c("div",null,[...a[0]||(a[0]=[d('<p>Ce menu propose des paramètres et des mécanismes importants pour l&#39;étalonnage.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  Paramètres moins courants<br>   Calibration avancée</p></div><h5 id="use-treatment-bg-values" tabindex="-1">Utiliser les valeurs BG des traitements <a class="header-anchor" href="#use-treatment-bg-values" aria-label="Permalink to &quot;Utiliser les valeurs BG des traitements {#use-treatment-bg-values}&quot;">​</a></h5><p>Vous pouvez choisir d&#39;utiliser les <a href="./../use/mainUI.html#treatments">traitements</a> de glycémie (tests sanguins) comme calibrations.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les valeurs BG des traitements</p><p> Indiquer si vous voulez calibrer avec la valeur de glycémie dans une saisie de Traitement</p></div><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Utiliser systématiquement les traitements comme calibrations <strong>n&#39;est pas recommandé</strong>.</p></div><p>Le mode automatique ne vous propose d&#39;utiliser le traitement comme calibration que si xDrip détecte que les conditions actuelles sont bonnes pour étalonner (glycémie stable depuis 20 minutes, faible bruit...).</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les valeurs BG des traitements</p><p> Automatic mode (best)<span style="float:right;">● </span>   <br>  Ask me every time<span style="float:right;">○ </span>   <br>  Never use them<span style="float:right;">○ </span>   <br>  Always use them<span style="float:right;">○ </span>   </p></div><p>Il peut aussi vous proposer d&#39;activer la calibration automatique.</p><p><strong>Il n&#39;est pas recommandé d&#39;utiliser cette fonction avec les capteurs G6/G7/ONE/ONE+.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Activer la calibration automatique</p><p> Les tests sanguins réalisés durant les périodes stables peuvent être utilisés pour recalibrer automatiquement 20 minutes après leur entrée. Ceci devrait être la méthode de calibration la plus précise.</p><p> Voulez-vous activer cette fonctionnalité ?</p><p> <span style="background-color:white;color:black;"> NON </span>    OUI, ACTIVER</p></div><p>Ask me every time vous posera exactement cette question à chaque saisie d&#39;un traitement de glycémie.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les glycémies capilaires pour la calibration?</p><p> Voulez-vous utiliser ce résultat de test de glycémie capillaire pour calibrer ?</p></div><p>Never use them n&#39;utilisera jamais les traitements pour étalonner (et vous empêchera de transformer un <a href="./../use/mainUI.html#treatments">traitement</a> en calibration).</p><h5 id="automatic-calibration" tabindex="-1">Calibration automatique <a class="header-anchor" href="#automatic-calibration" aria-label="Permalink to &quot;Calibration automatique {#automatic-calibration}&quot;">​</a></h5><p>Il est recommandé de <strong>la désactiver pour les capteurs G6/G7/ONE/ONE+</strong>.</p><p>La calibration automatique accepte un traitement comme calibration s&#39;il remplit la condition d&#39;une tendance plate pendant 20 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Calibration automatique <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Calibrer en utilisant les nouvelles valeurs de glycémies si les conditions semblent pouvoir le faire, sans demander confirmation (expérimental)</p></div><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins {#plugins}&quot;">​</a></h3><p>Des plugins de calibration sont disponibles dans xDrip, la plupart ne sont plus utilisés. Lorsqu&#39;il est activé, un plugin remplace la calibration standard de xDrip. L&#39;idée était de permettre de choisir un algorithme de calibration personnalisé, mais elle n&#39;a jamais été entièrement mise en œuvre. En règle générale, un capteur qui a besoin d&#39;un plugin pour être étalonné devrait être remplacé, par sécurité.</p><div class="warning custom-block"><p class="custom-block-title"><strong>SÉCURITÉ</strong></p><p><strong>Les mécanismes de sécurité de la calibration ne s&#39;appliquent pas aux plugins. Utiliser un plugin pour contourner un échec de calibration est dangereux.</strong></p></div><div class="admonition xdripitem"><p class="admonition-title">Plugin de Calibration</p><p> Plugin de calibration secondaire expérimental</p></div><div class="warning custom-block"><p class="custom-block-title">Extension Wear</p><p>Les plugins ne sont pas entièrement implémentés dans Wear. Vous pourriez voir des valeurs différentes sur votre montre.</p></div><div class="admonition xdripitem"><p class="admonition-title">Plugin de Calibration</p><p> None<br>  Datricsae - pronounced: da-trix-ee - highly experimental<br>  Fixed Slope Example - never use for real data<br>  xDrip Original - classic algorithm<br>  Last7Ua - Unweighted last 7 calibrations. Example only</p></div><p><strong><code>None</code></strong> : par défaut, l&#39;algorithme de xDrip est utilisé. <strong>Recommandé</strong></p><p><strong><code>Datricsae</code></strong> était apprécié de ceux qui avaient des difficultés avec l&#39;algorithme par défaut de xDrip. Il nécessite 8 points de calibration (en dessous de 4, l&#39;algorithme d&#39;origine de xDrip est utilisé) et limite la pente entre 0,5 et 1,7. Son principal atout est d&#39;écarter les valeurs aberrantes (mauvais points de calibration) trop éloignées de la droite de calibration. Après ce filtrage, si le nombre de points de calibration tombe sous 4 ou si la pente sort des limites, l&#39;algorithme classique de xDrip est utilisé.<br> Soyez prudent : des calibrations bruitées peuvent donner des résultats incohérents.</p><img src="'+n+'" style="zoom:75%;"><p><strong><code>Fixed slope</code></strong> est un plugin vide qui renvoie une pente de 1,08 et une ordonnée à l&#39;origine de -5. <strong>Ne l&#39;utilisez pas pour une glycémie réelle.</strong></p><p><strong><code>xDrip Original</code></strong> était l&#39;équivalent en plugin de l&#39;algorithme de xDrip. Il ne fait rien de plus que l&#39;algorithme de xDrip. <strong>L&#39;utiliser n&#39;apporte rien.</strong></p><p><strong><code>Last 7 unweighted</code></strong> était une première tentative d&#39;amélioration de l&#39;algorithme d&#39;origine. Il nécessite au moins 4 calibrations (il utilise jusqu&#39;aux 7 dernières ; en dessous de 4, l&#39;algorithme actuel de xDrip est utilisé). <strong>Non recommandé.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Tracés du Plugin sur le graphique <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Afficher les résultats de glycémie du plugin sur le graphique principal</p></div><p>Activez cette option si vous voulez que xDrip trace les résultats du plugin.</p><img src="'+o+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Utiliser la Glycémie du Plugin <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> L&#39;affichage des chiffres principaux de glucides proviennent du plugin !</p></div><p>Activez cette option si vous voulez que la valeur de glycémie principale provienne des résultats du plugin. Un P entouré s&#39;affiche alors.</p><img src="'+r+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Plugin surpasse tous les autres <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Toutes les nouvelles données de glycémie seront calculées et enregistrées du plugin sélectionné et non à partir de l&#39;algorithme standard xDrip. Ce n&#39;est pas testé et peut être inexacte et pleins de bug. Utiliser avec une extrême prudence.</p></div><p>Non implémenté.</p><h3 id="calibrations" tabindex="-1">Calibrations <a class="header-anchor" href="#calibrations" aria-label="Permalink to &quot;Calibrations {#calibrations}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Calibrations doubles <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Demander un second test sanguin optionnel pour la calibration initiale</p></div><p>Si vous ne faites pas réellement deux tests sanguins distincts pour la calibration initiale, désactivez cette option.</p><p>L&#39;ancienne méthode de calibration rétablit la plage d&#39;origine, plus étroite, des pentes autorisées dans l&#39;algorithme de calibration classique de xDrip (avant 2017), ce qui rend les pentes par défaut plus probables. Visible uniquement lorsque le Mode développeur est activé.</p><div class="admonition xdripitem"><p class="admonition-title">Ancienne méthode de calibration <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Plage plus étroite originale de pentes autorisées dans l&#39;algorithme de calibration classique xDrip (avant 2017). Les pentes par défaut sont plus probables !</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibrations peu fréquentes <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Si besoin, utiliser des calibrations plus anciennes, par exemple si les calibrations sont rarement saisies.</p></div><p>Les calibrations trop anciennes sont ignorées : si vous étalonnez rarement et voulez que des mesures de calibration plus anciennes pèsent sur la courbe de calibration actuelle, activez cette option.</p><h3 id="libre-specific" tabindex="-1">Spécifique au Libre <a class="header-anchor" href="#libre-specific" aria-label="Permalink to &quot;Spécifique au Libre {#libre-specific}&quot;">​</a></h3><h5 id="non-fixed-libre-slopes" tabindex="-1">Pentes du Libre non fixées <a class="header-anchor" href="#non-fixed-libre-slopes" aria-label="Permalink to &quot;Pentes du Libre non fixées {#non-fixed-libre-slopes}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Pentes du Libre non fixées <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Activer pour permettre les pentes variables avec les méthodes de collection Libre</p></div><p>Les capteurs Libre peuvent être difficiles à étalonner. Si vous n&#39;arrivez pas à obtenir une bonne précision sur toute la plage, ou si vous n&#39;étalonnez jamais dans la plage haute, désactivez cette option pour fixer la pente à 1. C&#39;est recommandé pour les débutants.</p><p><strong>Par sécurité, étalonnez toujours à glycémie stable, dans le bas de la plage normale.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Check Libre Serial <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Automatically stop if Libre Serial changes unexpectedly</p></div><p>Reporter les calibrations de l&#39;ancien capteur sur un nouveau est dangereux. <strong>Laissez cette option activée.</strong></p><h3 id="bypass-quality-check" tabindex="-1">Ignorer la vérification de qualité <a class="header-anchor" href="#bypass-quality-check" aria-label="Permalink to &quot;Ignorer la vérification de qualité {#bypass-quality-check}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Ignorer la vérification de qualité <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Permettre la calibration initiale même si nous n&#39;avons pas assez de bonnes données. Attention peut entraîner une calibration inexacte !</p></div><p>Lors des mesures préliminaires avant la première calibration, 3 mesures valides sont nécessaires. Si elles manquent ou ne respectent pas les valeurs de sécurité, xDrip attend. Activer cette option permet de calibrer sans vérification. <strong>Non recommandé.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Collecte des premières lectures</p><p> ✔ Collecteur de données en cours d&#39;exécution<br>  ✔ Réception des données du Collecteur MiaoMiao<br>  ✔ Reçu quelques données récentes<br>  ⧖ Reçu assez de bonnes données pour calibrer<br>  <strong>Need 3 recent readings, got only 1 so far</strong><br>  Next reading expected in 1 minute</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',58)])])}const k=l(u,[["render",m]]);export{D as __pageData,k as default};
